using System;
using System.Collections.Generic;

public class CycleDetection
{
    public bool HasCycle(List<Tuple<int, int>> edges)
    {
        Dictionary<int, List<int>> graph = new Dictionary<int, List<int>>();
        foreach (var edge in edges)
        {
            if (!graph.ContainsKey(edge.Item1))
            {
                graph[edge.Item1] = new List<int>();
            }
            graph[edge.Item1].Add(edge.Item2);
        }

        HashSet<int> visited = new HashSet<int>();
        HashSet<int> recursionStack = new HashSet<int>();

        foreach (var node in graph.Keys)
        {
            if (IsCyclic(node, graph, visited, recursionStack))
            {
                return true;
            }
        }
        return false;
    }

    private bool IsCyclic(int node, Dictionary<int, List<int>> graph, HashSet<int> visited, HashSet<int> recursionStack)
    {
        if (recursionStack.Contains(node))
        {
            return true;
        }
        if (visited.Contains(node))
        {
            return false;
        }

        visited.Add(node);
        recursionStack.Add(node);

        if (graph.ContainsKey(node))
        {
            foreach (var neighbor in graph[node])
            {
                if (IsCyclic(neighbor, graph, visited, recursionStack))
                {
                    return true;
                }
            }
        }

        recursionStack.Remove(node);
        return false;
    }
}
```

The `HasCycle` function constructs a graph from the given edges and then performs a depth-first search (DFS) to detect cycles in the graph. The `IsCyclic` function is a helper function that recursively checks for cycles using DFS. If a node is visited again while it's still in the recursion stack, it indicates the presence of a cycle in the graph.

